import {CopilotFreeUserChecklist} from './CopilotFreeUserChecklist'

export type UserPlan = 'free'

export interface CopilotUserChecklistProps {
  plan: UserPlan
  dismissed: boolean
  checklistState: boolean[]
  timeKey: number
}

export function CopilotUserChecklist({plan, dismissed, checklistState, timeKey}: CopilotUserChecklistProps) {
  switch (plan) {
    case 'free':
      return <CopilotFreeUserChecklist dismissed={dismissed} checklistState={checklistState} timeKey={timeKey} />
    default:
      return null
  }
}

try{ CopilotUserChecklist.displayName ||= 'CopilotUserChecklist' } catch {}